class Order:

    DISH_KEY = "dish"
    PRICE_KEY = "price"
    COUNT_KEY = "count"

    def __init__(self):
        self._menu = []
        # menu = [{"dish": dish name, "price": price, "count": count}, ...]
        self._selected_dishes = []
        # selected_dish = {"dish": dish name, "count": count, price: price}
        self._sales = {}

    @property
    def menu(self):
        return self._menu

    @menu.setter
    def menu(self, value):
        self._menu = value

    @property
    def selected_dishes(self):
        return self._selected_dishes

    @selected_dishes.setter
    def selected_dishes(self, value):
        self._selected_dishes = value

    @property
    def sales(self):
        return self._sales

    @sales.setter
    def sales(self, value):
        self._sales = value

    def _find_menu_dish(self, dish_name):
        for menu_dish in self.menu:
            if menu_dish[self.DISH_KEY] == dish_name:
                return menu_dish
        return None

    def _is_dish_available(self, menu_dish, requested_count):
        if menu_dish is None:
            return False
        return menu_dish[self.COUNT_KEY] >= requested_count

    def _deduct_from_menu(self, menu_dish, requested_count):
        menu_dish[self.COUNT_KEY] -= requested_count

    def add_dish(self, dish):
        dish_name = dish[self.DISH_KEY]
        requested_count = dish[self.COUNT_KEY]

        menu_dish = self._find_menu_dish(dish_name)

        if not self._is_dish_available(menu_dish, requested_count):
            return False

        self._deduct_from_menu(menu_dish, requested_count)
        self.selected_dishes.append(dish)
        return True

    def _calculate_dish_total(self, dish):
        return dish[self.PRICE_KEY] * dish[self.COUNT_KEY] * self.sales[dish[self.DISH_KEY]]

    def calculate_total(self):
        return sum(self._calculate_dish_total(dish) for dish in self.selected_dishes)

    def checkout(self):
        if not self.selected_dishes:
            return False
        total = self.calculate_total()
        self.selected_dishes = []
        return total
